## Code 4 — Reading a full line with `getline()` and displaying with `write()`
```cpp
#include <iostream>
using namespace std;

int main() {
    char name[20];  
    // Allocate an array of 20 characters (max input = 19 chars + '\0')

    cout << "Enter your name: ";
    cin.getline(name, 20);  
    // Reads a line of input until newline '\n' OR until 19 chars are read.
    // Unlike cin >> name, this does NOT stop at whitespace (so "John Doe" works).

    cout << "You entered: ";
    cout.write(name, 20);  
    // Writes exactly 20 characters (even garbage beyond '\0' if present).
    // Often you only use: cout << name; to avoid junk printing.

    return 0;
}
```

---

## Code 5 — Using `width()`, `precision()`, and `fill()` (formatted I/O)
```cpp
#include <iostream>
using namespace std;

int main() {
    double pi = 3.14159265;

    cout.width(10);          // field width = 10 spaces
    cout << 123 << endl;     // prints "       123" (right-aligned by default)

    cout.precision(4);       // only 4 significant digits
    cout << pi << endl;      // prints "3.142"

    cout.fill('*');          // fill empty spaces with '*'
    cout.width(10);
    cout << 456 << endl;     // prints "*******456"

    return 0;
}
```

---

## Code 6 — Using manipulators (`setw`, `setfill`, `setprecision`)
```cpp
#include <iostream>
#include <iomanip>   // required for manipulators like setw, setfill, setprecision
using namespace std;

int main() {
    double pi = 3.14159265;

    cout << setw(10) << 123 << endl;         // right-aligned in 10 spaces
    cout << setfill('-') << setw(10) << 456 << endl;  // fills unused spaces with '-'
    cout << setprecision(5) << pi << endl;   // sets precision to 5 digits

    cout << hex << 255 << endl;   // prints "ff" (hexadecimal)
    cout << dec << 255 << endl;   // prints "255" (decimal)

    return 0;
}
```

