## Code 10 — Nesting of member functions
```cpp
#include <iostream>
using namespace std;

class Student {
    int rollNo;
    char name[20];

public:
    void getdata() {
        cout << "Enter Roll No: ";
        cin >> rollNo;
        cout << "Enter Name: ";
        cin >> name;
    }

    void display() {
        showData();   // calling another member function inside the same class
    }

private:
    void showData() {
        cout << "Roll No = " << rollNo << endl;
        cout << "Name = " << name << endl;
    }
};

int main() {
    Student s;
    s.getdata();
    s.display();
    return 0;
}
