## Code 11 — Static data member example
```cpp
#include <iostream>
using namespace std;

class Student {
private:
    int rollNo;
    char name[20];
    int marks;

public:
    static int objectCount;   // shared across all objects

    Student() {
        objectCount++;        // increment whenever object is created
    }

    void getdata() {
        cout << "Enter roll number: ";
        cin >> rollNo;
        cout << "Enter name: ";
        cin >> name;
        cout << "Enter marks: ";
        cin >> marks;
    }

    void putdata() {
        cout << "Roll Number = " << rollNo << endl;
        cout << "Name = " << name << endl;
        cout << "Marks = " << marks << endl;
    }
};

// initialize static member outside class
int Student::objectCount = 0;

int main() {
    Student s1, s2;
    s1.getdata();
    s2.getdata();

    s1.putdata();
    s2.putdata();

    cout << "Total objects created = " << Student::objectCount << endl;
    return 0;
}
```

