## Code 12 — Static member function
```cpp
#include <iostream>
using namespace std;

class Counter {
    static int count;   // shared variable
public:
    static void increment() {
        count++;
    }

    static void showCount() {
        cout << "Count = " << count << endl;
    }
};

// initialize static variable
int Counter::count = 0;

int main() {
    Counter::increment(); // no object needed
    Counter::increment();
    Counter::showCount(); // prints 2
    return 0;
}
```

